-- Partner-preference age and height ranges: NULL now means "no limit".
--
-- These columns were NOT NULL with defaults of 18-45 and 140-210, so a range
-- nobody chose still filtered like a real one: a member who never set an age
-- excluded everyone over 45, and "Any" could not clear a saved range because
-- there was no value that meant "none".

-- AlterTable (generated by `prisma migrate diff`)
ALTER TABLE "partner_preferences" ALTER COLUMN "min_age" DROP NOT NULL,
ALTER COLUMN "min_age" DROP DEFAULT,
ALTER COLUMN "max_age" DROP NOT NULL,
ALTER COLUMN "max_age" DROP DEFAULT,
ALTER COLUMN "min_height_cm" DROP NOT NULL,
ALTER COLUMN "min_height_cm" DROP DEFAULT,
ALTER COLUMN "max_height_cm" DROP NOT NULL,
ALTER COLUMN "max_height_cm" DROP DEFAULT;

-- Existing rows still holding the old defaults become "no limit".
--
-- Height 140-210 cannot be picked in the app (every height preset maps to a
-- different range), so a row holding it was always the default.
UPDATE "partner_preferences"
SET "min_height_cm" = NULL, "max_height_cm" = NULL
WHERE "min_height_cm" = 140 AND "max_height_cm" = 210;

-- Age 18-45 is reachable on the age slider, so this may also clear a range a
-- member set on purpose. Accepted: it was overwhelmingly written as the
-- default (every preference row created without an age got it), and a member
-- who did choose it keeps a feed that is only wider, never narrower.
UPDATE "partner_preferences"
SET "min_age" = NULL, "max_age" = NULL
WHERE "min_age" = 18 AND "max_age" = 45;
